Решение. 
Считаем числа из файла в массив, после чего отсортируем его. Для поиска суммы двух чисел разной чётности из массива будем использовать бинарный поиск. Для этого создадим специальную функцию, которая будет возвращать значение True, если в массиве будет найдено искомое значение. В этом случае в переменной count будем накапливать единицу. Также в переменную maxSum будем записывать максимальное найденное значение, удовлетворяющее условиям.
Приведём решение на языке PascalABC.
type mt = array [1..5000] of integer;
var 
 n, i, j, t, sum, count, maxSum: integer;
 arr: mt;
 f: text;
function binSearch(left, right, num: integer; arr: mt):boolean;
 var mid: integer;
 begin
 while right > left + 1 do begin
 mid := (left + right) div 2;
 if arr[mid] > num then right := mid
 else if arr[mid] arr[j] then begin
 t := arr[i];
 arr[i] := arr[j];
 arr[j] := t;
 end;
 count := 0;
 maxSum := 0;
 for i := 1 to n - 1 do begin
 for j := i + 1 to n do begin
 if ((arr[i] + arr[j]) mod 2 = 1) then begin
 sum := arr[i] + arr[j];
 if binSearch(i, n, sum, arr) then begin
 count := count + 1;
 if sum > maxSum then maxSum := sum;
 end;
 end;
 end;
 end; 
 writeln(count, ' ', maxSum);
end.
