Решение. 
Создадим два двумерных массива. В первый массив считаем все элементы из файла и отсортируем его по возрастанию. После этого посчитаем максимальное количество изделий, которое можем закупить на заданную сумму, последовательно прибавляя к переменной sum цену изделия в текущем элементе. Далее в отдельный двумерный массив вынесем только оставшиеся изделия B. Далее будем перебирать уже взятые изделия с конца, пытаясь заменить изделия A на изделия B таким образом, чтобы сумма взятых изделий не превышала заданную сумму. После этого посчитаем, сколько изделий B получилось закупить.
Приведём решение на языке Pascal.
var 
 n, m, x, t1, t2, countB, count, i, j: integer;
 z: string;
 arrayAB: array [1..916, 1..2] of integer;
 arrayB: array [1..916, 1..2] of integer;
 sum: integer;
 f: text;
begin
 assign(f,'C:\26.txt');
 reset(f);
 readln(f, n, m);
 countB := 0;
 count := 0;
 sum := 0;
 for i := 1 to n do begin
 if not eof(f) then
 readln(f, x, z)
 else break;
 if z.Contains('A') then begin
 arrayAB[i, 1] := x;
 arrayAB[i, 2] := 0;
 end;
 if z.Contains('B') then begin
 arrayAB[i, 1] := x;
 arrayAB[i, 2] := 1;
 end;
 end;
 for i := 1 to n-1 do
 for j := i + 1 to n do 
 if arrayAB[i, 1] > arrayAB[j, 1] then begin
 t1 := arrayAB[i, 1];
 t2 := arrayAB[i, 2];
 arrayAB[i, 1] := arrayAB[j, 1];
 arrayAB[i, 2] := arrayAB[j, 2];
 arrayAB[j, 1] := t1;
 arrayAB[j, 2] := t2;
 end;
 for i := 1 to n do
 if (sum + arrayAB[i, 1]) m) then break;
 sum := sum - arrayAB[i, 1] + arrayB[x, 1];
 arrayAB[i, 1] := arrayB[x, 1];
 arrayAB[i, 2] := arrayB[x, 2];
 x := x + 1;
 end;
 end;
 for i := 1 to count do
 if arrayAB[i, 2] = 1 then countB := countB + 1;
 writeln(countB, ' ', m - sum);
end.
