 arrayA: array [1..916, 1..2] of integer;
 sum: integer;
 f: text;
begin
 assign(f,'C:\26.txt');
 reset(f);
 readln(f, n, m);
 countA := 0;
 count := 0;
 sum := 0;
 for i := 1 to n do begin
 if not eof(f) then
 readln(f, x, z)
 else break;
 if z.Contains('A') then begin
 arrayAB[i, 1] := x;
 arrayAB[i, 2] := 0;
 end;
 if z.Contains('B') then begin
 arrayAB[i, 1] := x;
 arrayAB[i, 2] := 1;
 end;
 end;
 for i := 1 to n-1 do
 for j := i + 1 to n do 
 if arrayAB[i, 1] > arrayAB[j, 1] then begin
 t1 := arrayAB[i, 1];
 t2 := arrayAB[i, 2];
 arrayAB[i, 1] := arrayAB[j, 1];
 arrayAB[i, 2] := arrayAB[j, 2];
 arrayAB[j, 1] := t1;
 arrayAB[j, 2] := t2;
 end;
 for i := 1 to n do
 if (sum + arrayAB[i, 1]) m) then break;
 sum := sum - arrayAB[i, 1] + arrayA[x, 1];
 arrayAB[i, 1] := arrayA[x, 1];
 arrayAB[i, 2] := arrayA[x, 2];
 x := x + 1;
 end;
 end;
 for i := 1 to count do
 if arrayAB[i, 2] = 0 then countA := countA + 1;
 writeln(countA, ' ', m - sum);
end.
